package kz.scanai


/**
 * Offline assistant: answers only questions about glucose and health, using the user's own readings.
 * Rule-based (no network); gives general guidance, never doses or prescriptions.
 */
object LocalBot {
    private val MEDICAL = listOf("сахар", "глюкоз", "диабет", "инсулин", "гликем", "здоров", "самочувств", "давлен", "пульс", "врач",
        "лекарств", "таблетк", "препарат", "симптом", "болит", "боль", "слабост", "головокруж", "жажд", "голод", "еда", "есть", "пить",
        "выпить", "диет", "питан", "спорт", "трениров", "сон", "стресс", "анализ", "норма", "ммоль", "замер", "скан", "глюкометр",
        "тошнит", "усталост", "вес", "похуд", "углевод", "сладк", "фрукт", "хлеб", "вода", "чай", "кофе", "сок", "скорая", "обморок",
        "холестерин", "температур", "устал", "потею", "дрож", "мочеиспуск", "гипо", "гипер", "ацетон", "точн", "камер", "измер")

    private fun has(q: String, vararg keys: String) = keys.any { q.contains(it) }

    private fun zone(v: Double) = when {
        v < 3.0 -> "очень низкий"
        v < 3.9 -> "низкий"
        v < 5.6 -> "в норме"
        v < 7.8 -> "в норме (для времени после еды)"
        v < 10.0 -> "повышен"
        v < 13.9 -> "высокий"
        else -> "очень высокий"
    }

    private fun context(readings: List<Reading>, who: String = ""): String {
        val last = readings.lastOrNull() ?: return ""
        val prev = readings.dropLast(1).lastOrNull()
        val trend = prev?.let {
            val d = last.mmol - it.mmol
            when { d > 0.5 -> "Растёт по сравнению с прошлым замером (%.1f)".format(it.mmol)
                d < -0.5 -> "Снижается по сравнению с прошлым замером (%.1f)".format(it.mmol)
                else -> "Почти не изменился с прошлого замера (%.1f)".format(it.mmol) }
        }
        return "${if (who.isBlank()) "Ваш" else "$who, ваш"} последний замер: %.1f ммоль/л, %s.${trend?.let { " $it." } ?: ""}\n\n".format(last.mmol, zone(last.mmol))
    }

    fun reply(question: String, readings: List<Reading>, name: String = "", diagnosis: String = ""): String {
        val q = question.lowercase().replace('ё', 'е')
        val last = readings.lastOrNull()?.mmol
        val ctx = context(readings, name)
        val dx = if (diagnosis.isBlank() || diagnosis == "Нет диагноза") "" else "\n\nУчитывая ваш диагноз (${diagnosis.lowercase()}), любые изменения в лечении согласуйте с врачом."

        if (has(q, "скорая", "обморок", "потерял сознан", "без сознан", "ацетон", "рвота", "рвет", "сильная боль в груди", "задыха", "судорог"))
            return "Это тревожные признаки.\n\n• Позвоните 103 или 112 прямо сейчас.\n• Не оставайтесь один, лягте или сядьте.\n• Если есть глюкометр, измерьте сахар и назовите значение врачам.\n• Если человек без сознания, ничего не давайте пить и есть.\n\nНе ждите, пока пройдёт само."

        if (has(q, "привет", "здравств", "добрый", "салем", "hello", "hi "))
            return "${if (name.isBlank()) "Здравствуйте" else "Привет, $name"}! Я мини-ИИ ScanAI, отвечаю про глюкозу и здоровье. ${if (last != null) "Вижу ваш замер: %.1f ммоль/л, ${zone(last)}.".format(last) else "Сделайте скан, и я дам советы по результату."}\n\nСпросите, например: «что делать при высоком сахаре?» или «что выпить?»."

        if (has(q, "спасибо", "благодар")) return "Пожалуйста! Берегите себя. Если сахар будет расти или появятся симптомы, напишите, подскажу."

        if (has(q, "лекарств", "таблетк", "препарат", "инсулин", "метформин", "дозировк", "доза", "сколько принимать"))
            return ctx + "По лекарствам:\n\n• Препараты от диабета и их дозы подбирает только врач. Я не назначаю лекарства и дозы.\n• Принимайте то, что назначено, по схеме. Не пропускайте и не отменяйте сами.\n• Если сахар стабильно выше 10 или ниже 3,9, сообщите врачу: схему могут скорректировать.\n• Не принимайте чужие таблетки и «народные» средства вместо лечения.\n• Вопросы к врачу: нужна ли коррекция, как принимать при болезни и спорте.$dx"

        if (has(q, "низк", "гипо", "упал", "дрож", "потею", "слабост от голода", "сахар упал") && !has(q, "высок"))
            return ctx + "Если сахар низкий (ниже 3,9) или есть дрожь, пот, резкий голод:\n\n1. Сразу съешьте или выпейте 15 г быстрых углеводов: полстакана сока, 3–4 кусочка сахара или таблетки глюкозы.\n2. Через 15 минут измерьте снова. Если всё ещё ниже 3,9, повторите.\n3. Когда поднимется, съешьте что-то посложнее (хлеб, кашу, фрукт).\n4. Если ниже 3,0, человек вялый или путается, не может пить, вызывайте 103/112.\n\nПотом расскажите врачу о таком эпизоде."

        if (has(q, "высок", "повышен", "много сахара", "гипер", "выше нормы", "поднялся", "вырос", "скачок", "что делать") && !has(q, "давлен"))
            return when {
                last == null -> "При высоком сахаре:\n\n• Выпейте воды, пройдитесь 10–15 минут, если нет плохого самочувствия.\n• Не ешьте сладкое и быстрые углеводы.\n• Измерьте глюкометром и повторите через 1–2 часа.\n• Если выше 13,9 с жаждой, тошнотой, слабостью, запахом ацетона, вызывайте 103.\n\nСделайте скан, и я дам советы под ваш результат."
                last < 7.8 -> ctx + "Сейчас сахар в пределах нормы, повода для паники нет. Чтобы он оставался ровным: пейте воду, не пропускайте приёмы пищи, после еды гуляйте 10–15 минут."
                last < 10.0 -> ctx + "Сахар слегка повышен.\n\n• Выпейте стакан воды, пройдитесь 10–15 минут.\n• В ближайшие часы без сладкого, белого хлеба, соков.\n• Следующий приём: белок и овощи, а не только углеводы.\n• Повторите замер через 1–2 часа. Если не снижается или есть жажда, скажите врачу."
                last < 13.9 -> ctx + "Сахар высокий.\n\n• Пейте воду небольшими глотками, в течение часа 2–3 стакана.\n• Лёгкая ходьба 10–15 минут, если нет слабости.\n• Исключите быстрые сахара и сладкие напитки.\n• Если вам назначены препараты, примите их по схеме врача, не увеличивайте дозу сами.\n• Повторите замер через час. Если выше 13,9 или есть жажда, тошнота, слабость, свяжитесь с врачом сегодня."
                else -> ctx + "Сахар очень высокий, это требует внимания.\n\n• Пейте воду, не ешьте сладкое.\n• Сегодня же свяжитесь с врачом.\n• Если есть тошнота, рвота, сильная жажда, запах ацетона, слабость, спутанность, звоните 103 или 112.\n• Проверьте значение глюкометром: камера даёт только ориентир."
            }

        if (has(q, "выпить", "пить", "напит", "вода", "чай", "кофе", "сок", "компот"))
            return ctx + "Что пить:\n\n• Лучше всего вода, 1,5–2 литра в день, особенно при повышенном сахаре.\n• Чай и кофе без сахара допустимы.\n• Избегайте соков, лимонадов, сладких чаёв: они резко поднимают сахар.\n• Исключение: при низком сахаре (ниже 3,9) полстакана сока или сладкой воды помогут быстро.\n• Алкоголь может вызывать скачки и опасные падения, лучше избегать."

        if (has(q, "еда", "есть", "съесть", "питан", "диет", "продукт", "завтрак", "ужин", "обед", "сладк", "хлеб", "фрукт", "углевод", "каша", "рис"))
            return ctx + "Питание для ровного сахара:\n\n• Основа: овощи, белок (рыба, яйца, мясо, творог), цельнозерновые каши.\n• Углеводы лучше медленные: гречка, овсянка, бобовые, цельнозерновой хлеб.\n• Меньше: сахар, сладости, белый хлеб, выпечка, сладкие напитки, белый рис.\n• Фрукты в меру, лучше яблоко, ягоды, цитрусовые, чем виноград и бананы.\n• Порядок на тарелке: сначала овощи и белок, потом углеводы: после еды сахар растёт мягче.\n• После еды 10–15 минут ходьбы."

        if (has(q, "норм", "какой должен", "показател", "ммоль", "значение", "диапазон"))
            return "Ориентиры сахара в крови (ммоль/л, глюкометр):\n\n• Натощак: 3,9–5,5.\n• Через 2 часа после еды: до 7,8.\n• 5,6–6,9 натощак: «серая зона», стоит обсудить с врачом.\n• 7,0 и выше натощак или 11,1 и выше в любое время: повод обратиться к врачу.\n• Ниже 3,9: низкий сахар, нужны быстрые углеводы.\n\n${if (last != null) "Ваш замер %.1f: ${zone(last)}.".format(last) else ""}"

        if (has(q, "оцени", "мой замер", "мой сахар", "результат", "как мои", "что значит", "мой показатель", "как у меня", "замер"))
            return if (last == null) "Пока нет замеров. Откройте вкладку ЗАМЕР и нажмите «СКАНИРОВАТЬ», затем спросите снова."
            else ctx + when {
                last < 3.9 -> "Значение низкое. Съешьте 15 г быстрых углеводов (сок, сахар, глюкоза) и измерьте через 15 минут."
                last < 7.8 -> "Это в пределах нормы. Продолжайте: вода, регулярное питание, ходьба после еды."
                last < 10.0 -> "Сахар повышен. Выпейте воды, пройдитесь и избегайте быстрых сахаров. Повторите замер через 1–2 часа."
                else -> "Сахар высокий. Пейте воду, исключите сладкое, свяжитесь с врачом. Если есть тошнота, сильная жажда, слабость, звоните 103."
            } + "\n\nНапоминаю: скан камерой это исследовательский ориентир. Для решений опирайтесь на глюкометр."

        if (has(q, "спорт", "трениров", "ходьб", "прогул", "физ", "бег"))
            return ctx + "Активность и сахар:\n\n• 10–15 минут ходьбы после еды заметно снижают подъём сахара.\n• Регулярные нагрузки (150 минут в неделю умеренной активности) помогают держать сахар ровным.\n• Не тренируйтесь, если сахар ниже 4 или выше 13 с плохим самочувствием.\n• Берите с собой быстрые углеводы и воду."

        if (has(q, "сон", "стресс", "нервы", "устал", "усталост", "тревог"))
            return "Сон и стресс влияют на сахар:\n\n• Недосып и стресс повышают гормоны, из-за которых сахар растёт.\n• Старайтесь спать 7–8 часов.\n• Помогают прогулки, дыхание (4 секунды вдох, 6 выдох), перерывы в работе.\n• Если постоянная усталость и жажда, сдайте анализ и обсудите с врачом."

        if (has(q, "симптом", "жажд", "часто мочеиспуск", "мочеиспуск", "слабост", "головокруж", "тошнит", "голод", "болит", "боль"))
            return ctx + "Тревожные признаки повышенного сахара: сильная жажда, частое мочеиспускание, слабость, сухость во рту, туман в голове, потеря веса без причины.\nПризнаки низкого: дрожь, пот, резкий голод, головокружение, раздражительность.\n\n• Если признаки есть, измерьте сахар глюкометром и действуйте по значению.\n• Тошнота, рвота, запах ацетона, спутанность, обморок: сразу 103/112.\n• Если симптомы повторяются, запишитесь к врачу (терапевт, эндокринолог)."

        if (has(q, "врач", "анализ", "гликирован", "hba1c", "диабет", "когда идти", "обратиться"))
            return "К врачу стоит обратиться, если:\n\n• Сахар натощак 5,6 и выше несколько дней или 7,0 и выше.\n• После еды стабильно выше 7,8–10.\n• Есть жажда, частое мочеиспускание, слабость, потеря веса.\n• Низкий сахар повторяется.\n\nПолезные анализы: глюкоза натощак, гликированный гемоглобин (HbA1c), при необходимости тест на толерантность к глюкозе. Лучше начать с терапевта или эндокринолога."

        if (has(q, "точн", "камер", "как измер", "глюкометр", "измер", "скан", "доверять"))
            return "Скан камерой в ScanAI это исследовательский ориентир: приложение читает пульсовую волну с пальца, и точность ещё проверяется на данных. Для решений о лечении и еде опирайтесь на глюкометр. Хорошо сканировать: палец плотно на камере и вспышке, рука неподвижна, 36 секунд."

        if (has(q, "пульс", "давлен"))
            return "Пульс и давление не заменяют измерение сахара, но связаны с самочувствием. Нормальный пульс в покое 60–90 уд/мин. Если пульс стабильно выше 100 или ниже 50, есть головокружение, боль в груди, одышка, обратитесь к врачу, при сильных симптомах звоните 103."

        val medical = MEDICAL.any { q.contains(it) }
        return if (!medical)
            "Я отвечаю только на вопросы про глюкозу и здоровье. Спросите, например: «что делать при высоком сахаре?», «что выпить?», «какая норма?» или «оцени мой замер»."
        else ctx + "Могу подсказать по этим темам: высокий или низкий сахар, что пить и есть, лекарства (общая информация), симптомы, нормы, когда к врачу, спорт и сон. Уточните вопрос, пожалуйста."
    }
}
